import AppKit
import SwiftUI

/// Mountain's logo mark (white, transparent background, inner stroke cut out),
/// made by `tools/make-icon.swift` and embedded so it needs no resource bundle.
/// It stays Mountain's property — see the README.
enum MountainMark {
    private static let png = ""

    /// The white mark, ~2.9 : 1.
    static let image: NSImage = Data(base64Encoded: png).flatMap { NSImage(data: $0) } ?? NSImage()

    static var aspect: CGFloat { image.size.height > 0 ? image.size.width / image.size.height : 2.9 }

    /// Menu-bar icon: a template image (macOS tints it for light, dark and
    /// the highlighted state). `warning` adds a dot, as a cut-out ring so it
    /// reads in one colour too.
    static func menuBarImage(warning: Bool) -> NSImage {
        let size = NSSize(width: warning ? 35 : 28, height: 18)
        let img = NSImage(size: size, flipped: false) { rect in
            let w: CGFloat = 26, h = w / MountainMark.aspect
            MountainMark.image.draw(in: NSRect(x: 1, y: (rect.height - h) / 2 - 0.5, width: w, height: h),
                                    from: .zero, operation: .sourceOver, fraction: 1)
            if warning, let ctx = NSGraphicsContext.current?.cgContext {
                let c = CGPoint(x: 30.2, y: 13.2)
                ctx.setBlendMode(.clear)
                ctx.fillEllipse(in: CGRect(x: c.x - 4.6, y: c.y - 4.6, width: 9.2, height: 9.2))
                ctx.setBlendMode(.normal)
                ctx.setFillColor(NSColor.black.cgColor)
                ctx.fillEllipse(in: CGRect(x: c.x - 3.2, y: c.y - 3.2, width: 6.4, height: 6.4))
            }
            return true
        }
        img.isTemplate = true
        return img
    }
}

/// The logo on its blue tile, for the sidebar.
struct BrandTile: View {
    var size: CGFloat = 32

    var body: some View {
        ZStack {
            RoundedRectangle(cornerRadius: size * 0.26, style: .continuous)
                .fill(LinearGradient(colors: [Color(hex: 0x2A66FF), Color(hex: 0x0038E6)],
                                     startPoint: .top, endPoint: .bottom))
            RoundedRectangle(cornerRadius: size * 0.26, style: .continuous)
                .strokeBorder(.white.opacity(0.18), lineWidth: 0.8)
            Image(nsImage: MountainMark.image)
                .resizable()
                .interpolation(.high)
                .aspectRatio(contentMode: .fit)
                .frame(width: size * 0.68)
        }
        .frame(width: size, height: size)
        .shadow(color: Color(hex: 0x0044FF).opacity(0.45), radius: size * 0.22, y: size * 0.06)
    }
}
